@Composable
fun ListaAlunoScreen(
    viewModel: ListaAlunoViewModel = hiltViewModel()
) {
    val uiState by viewModel.alunos.collectAsStateWithLifecycle()

    ListaAlunoContent(
        ativos = uiState.ativos,
        inativos = uiState.inativos
    )
}

@OptIn(ExperimentalMaterial3Api::class, ExperimentalFoundationApi::class)
@Composable
fun ListaAlunoContent(
    ativos: List<Aluno>,
    inativos: List<Aluno>,
    onEvent: (ListaEvento) -> Unit = {}
) {
    val scrollBehavior = TopAppBarDefaults.exitUntilCollapsedScrollBehavior()
    val listState = rememberLazyListState()
    val isEmpty = ativos.isEmpty() && inativos.isEmpty()
    var ativosExpanded by rememberSaveable { mutableStateOf(true) }
    var inativosExpanded by rememberSaveable { mutableStateOf(true) }

    Scaffold(
        modifier = Modifier.nestedScroll(scrollBehavior.nestedScrollConnection),
        topBar = {
            ListaAlunoTopBar(scrollBehavior = scrollBehavior)
        }
    ) { paddingValues ->
        if (isEmpty) {
            ListaAlunoEmpty(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(paddingValues)
            )
            return@Scaffold
        }

        LazyColumn(
            state = listState,
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues),
            contentPadding = PaddingValues(all = MaterialTheme.spacing.large),
            verticalArrangement = Arrangement.spacedBy(MaterialTheme.spacing.small)
        ) {
            alunoSection(
                headerKey = "header_ativos",
                headerTitleRes = R.string.lista_aluno_categoria_ativos,
                alunos = ativos,
                expanded = ativosExpanded,
                onToggleExpanded = { ativosExpanded = !ativosExpanded },
                onEvent = onEvent
            )
            alunoSection(
                headerKey = "header_inativos",
                headerTitleRes = R.string.lista_aluno_categoria_inativos,
                alunos = inativos,
                expanded = inativosExpanded,
                onToggleExpanded = { inativosExpanded = !inativosExpanded },
                onEvent = onEvent
            )
        }
    }
}

@OptIn(ExperimentalFoundationApi::class)
private fun LazyListScope.alunoSection(
    headerKey: String,
    @StringRes headerTitleRes: Int,
    alunos: List<Aluno>,
    expanded: Boolean,
    onToggleExpanded: () -> Unit,
    onEvent: (ListaEvento) -> Unit
) {
    if (alunos.isEmpty()) return

    stickyHeader(key = headerKey, contentType = "header") {
        ListaSectionHeader(
            titleRes = headerTitleRes,
            count = alunos.size,
            expanded = expanded,
            onToggle = onToggleExpanded,
            modifier = Modifier
                .fillMaxWidth()
                .background(MaterialTheme.colorScheme.surface)
                .padding(horizontal = MaterialTheme.spacing.large)
        )
    }

    if (!expanded) return

    items(alunos, key = { it.id }, contentType = { "aluno" }) { aluno ->
        AlunoItem(
            aluno = aluno,
            modifier = Modifier.animateItem(),
            onItemClick = { onEvent(ListaEvento.Detalhes(aluno.id)) }
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun ListaAlunoTopBar(scrollBehavior: TopAppBarScrollBehavior) {
    TopAppBar(
        title = {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Icon(
                    imageVector = Icons.Outlined.School,
                    contentDescription = stringResource(R.string.app_name),
                    modifier = Modifier.size(28.dp),
                    tint = MaterialTheme.colorScheme.primary
                )
                Spacer(modifier = Modifier.width(MaterialTheme.spacing.small))
                Text(stringResource(R.string.lista_aluno_screen_title))
            }
        },
        scrollBehavior = scrollBehavior
    )
}


@Composable
fun ListaAlunoEmpty(modifier: Modifier = Modifier) {
    Box(
        modifier = modifier,
        contentAlignment = Alignment.Center
    ) {
        Column(horizontalAlignment = Alignment.CenterHorizontally) {
            Icon(
                imageVector = Icons.Default.SearchOff,
                contentDescription = null,
                modifier = Modifier.size(48.dp),
                tint = MaterialTheme.colorScheme.onPrimaryContainer
            )
            Spacer(modifier = Modifier.height(MaterialTheme.spacing.extraSmall))
            Text(
                text = stringResource(R.string.lista_aluno_empty),
                style = MaterialTheme.typography.titleMedium
            )
        }
    }
}

/** Previews */
@Preview(showBackground = true)
@Composable
private fun ListaAlunoPreview() {
    AppTheme {
        ListaAlunoContent(
            ativos = PreviewData.alunos.filter { it.ativo },
            inativos = PreviewData.alunos.filterNot { it.ativo }
        )
    }
}

@Preview(showBackground = true)
@Composable
private fun ListaAlunoEmptyPreview() {
    AppTheme {
        ListaAlunoContent(
            ativos = emptyList(),
            inativos = emptyList()
        )
    }
}

